// Aggregate everything we know about the customer currently in the loop.
const customer = $('Split In Batches').first().json;

let emails = [];
try {
  emails = $('Gmail - Get Emails').all().filter(i => i.json && i.json.id);
} catch (e) { emails = []; }

let slackMessages = [];
try {
  slackMessages = $('Slack - Search Mentions').all().filter(i => i.json && (i.json.ts || i.json.text));
} catch (e) { slackMessages = []; }

// Bitrix24 returns false/empty for missing fields - normalise to null.
const clean = (v) => (v === false || v === 'false' || v === '' || v === undefined) ? null : v;

return [{
  json: {
    customer_id: String(customer.id),
    name: clean(customer.name),
    email: clean(customer.email),
    phone: clean(customer.phone),
    total_emails: emails.length,
    total_slack_messages: slackMessages.length,
    last_synced_at: new Date().toISOString()
  }
}];

// Accepts two shapes on purpose.
//
// 1. Supabase v_customer_directory — already {id, name, email, phone}. The HTTP
//    node may hand these over as one item per row, or as a single item holding
//    the whole array, depending on version; handle both.
// 2. The old Bitrix24 envelope — { result: [ {ID, NAME, EMAIL:[{VALUE}] ...} ] }.
//    Kept so that pointing the source back at the CRM needs no edit here.
const raw = $input.all().map(i => i.json);

if (raw.length === 1 && raw[0] && Array.isArray(raw[0].result)) {
  const first = (a) => Array.isArray(a) && a.length ? (a[0].VALUE || null) : null;
  return raw[0].result.map(c => ({ json: {
    id: String(c.ID),
    name: [c.NAME, c.LAST_NAME].filter(Boolean).join(' ').trim() || c.TITLE || null,
    email: first(c.EMAIL),
    phone: first(c.PHONE)
  } })).filter(i => i.json.email || i.json.phone);
}

let rows = raw;
if (raw.length === 1 && Array.isArray(raw[0])) rows = raw[0];

return rows
  .filter(r => r && (r.email || r.phone))
  .map(r => ({ json: {
    id: String(r.id != null ? r.id : (r.email || '')),
    name: r.name != null ? r.name : (r.customer_name || null),
    email: r.email || null,
    phone: r.phone || null
  } }));

// Every node whose success the Audit Log below is about to claim.
// Gmail / Slack are reads: losing them does not undo anything and the profile
// row still lands, so they are PARTIAL, not FAILED - but the counts written to
// customer_360_profiles are then guesses and must be named, never hidden.
const CLAIMED = [
  { node: 'Supabase - Upsert Profile', what: 'customer_360_profiles upsert', critical: true },
  { node: 'Gmail - Get Emails',        what: 'Gmail history for this customer', critical: false },
  { node: 'Slack - Search Mentions',   what: 'Slack mentions for this customer', critical: false },
];

function check(c) {
  let items;
  try { items = $(c.node).all(); }
  catch (e) { return { ...c, ok: false, why: 'node did not run on this branch' }; }
  if (!items.length) return { ...c, ok: false, why: 'node produced no items' };
  const j = items[0].json || {};
  if (j.error !== undefined) {
    const m = j.error && (j.error.message || j.error.description) || j.error;
    return { ...c, ok: false, why: String(m).slice(0, 300) };
  }
  return { ...c, ok: true };
}

const results  = CLAIMED.map(check);
const dropped  = results.filter(r => !r.ok);
const fatal    = dropped.filter(r => r.critical);

const status = fatal.length  ? 'FAILED'
             : dropped.length ? 'PARTIAL'
             : 'SUCCESS';

// The upsert runs with Prefer: return=minimal, so its own output carries no
// profile fields. Read them back from the node that built them.
let profile = {};
try { profile = $('Transform & Unify').first().json || {}; } catch (e) { profile = {}; }

// A read that ERRORED is not a read that found NOTHING.
// `Transform & Unify` filters both Gmail and Slack down to items that look like
// real results (`i.json.id`, `i.json.ts || i.json.text`). An {error:...} item
// emitted by onError:'continueRegularOutput' survives neither filter, so it is
// counted as zero. That is why this workflow reported "0 email(s), 0 Slack
// mention(s)" for months while both calls were in fact failing: a broken read
// and an empty inbox produce byte-identical numbers there.
// Nothing downstream of this node writes to customer_360_profiles - the upsert
// has already run - so refusing to state a count here changes only what we
// CLAIM, never what was stored.
const by = {};
for (const r of results) by[r.node] = r;
const gmailOk = !!(by['Gmail - Get Emails'] && by['Gmail - Get Emails'].ok);
const slackOk = !!(by['Slack - Search Mentions'] && by['Slack - Search Mentions'].ok);

const emailsTxt = gmailOk
  ? ((profile.total_emails ?? 0) + ' email(s)')
  : 'email count UNKNOWN - Gmail read failed';
const slackTxt = slackOk
  ? ((profile.total_slack_messages ?? 0) + ' Slack mention(s)')
  : 'Slack count UNKNOWN - Slack read failed';

// Each reason is trimmed so the whole line survives the 500-char audit summary.
// The reason string is the only place the ACTUAL API error text is ever written
// down anywhere - execution data is pruned, and both nodes swallow their error.
const reasons = dropped.map(r => r.what + ' - ' + String(r.why).slice(0, 90));

const note = dropped.length
  ? dropped.length + ' of ' + results.length + ' claimed steps did not land'
  : 'all ' + results.length + ' claimed steps verified';

const audit_summary = ('Profile upsert - ' + emailsTxt + ', ' + slackTxt + '. ' + note
  + (reasons.length ? ': ' + reasons.join(' | ') : '')).substring(0, 500);

return [{ json: {
  ...profile,
  ...( $input.first().json || {} ),
  // null, not 0: we do not know, and 0 is an assertion.
  total_emails:         gmailOk ? (profile.total_emails ?? null) : null,
  total_slack_messages: slackOk ? (profile.total_slack_messages ?? null) : null,
  delivery: {
    status,
    verified: results.filter(r => r.ok).map(r => r.what),
    dropped:  reasons,
    note,
    audit_summary,
  },
} }];
